        Console.WriteLine($"  {msg.Text}");
});

Console.WriteLine();
Console.WriteLine("=== Csc COMMAND LINES ===");
build.VisitAllChildren<Task>(task => {
    if (task.Name == "Csc") {
        var parent = task.Parent;
        while (parent != null && parent is not Project)
            parent = parent.Parent;
